using Essco.Domain.Inventory;
namespace Essco.Application.Inventory;

public interface IInventoryRepository { ValueTask<IReadOnlyCollection<PhysicalInventory>> ListAsync(CancellationToken token); ValueTask<PhysicalInventory?> GetAsync(int id, CancellationToken token); ValueTask<IReadOnlyCollection<InventoryItem>> ListItemsAsync(int id, CancellationToken token); ValueTask<IReadOnlyCollection<InventoryCount>> ListCountsAsync(int id, string? group, CancellationToken token); ValueTask<bool> SaveCountAsync(InventoryCount count, CancellationToken token); ValueTask<IReadOnlyCollection<InventoryGroup>> ListGroupsAsync(int id, CancellationToken token); ValueTask<bool> SaveGroupAsync(InventoryGroup group, CancellationToken token); ValueTask<bool> DeleteGroupAsync(int id, string code, string supplier, CancellationToken token); ValueTask<bool> CloseAsync(int id, decimal entries, decimal exits, CancellationToken token); }
public sealed class InventoryService(IInventoryRepository repository) { public ValueTask<IReadOnlyCollection<PhysicalInventory>> ListAsync(CancellationToken t) => repository.ListAsync(t); public ValueTask<PhysicalInventory?> GetAsync(int id, CancellationToken t) => repository.GetAsync(id, t); public ValueTask<IReadOnlyCollection<InventoryItem>> ListItemsAsync(int id, CancellationToken t) => repository.ListItemsAsync(id, t); public ValueTask<IReadOnlyCollection<InventoryCount>> ListCountsAsync(int id, string? g, CancellationToken t) => repository.ListCountsAsync(id, g, t); public async ValueTask<(bool Succeeded, IReadOnlyCollection<string> Errors)> SaveCountAsync(InventoryCount x, CancellationToken t) { var e = x.Validate(); if (e.Count > 0) return (false, e); return await repository.SaveCountAsync(x, t) ? (true, []) : (false, ["El conteo dejó de estar disponible o el inventario está cerrado."]); } public ValueTask<IReadOnlyCollection<InventoryGroup>> ListGroupsAsync(int id, CancellationToken t) => repository.ListGroupsAsync(id, t); public async ValueTask<(bool Succeeded, IReadOnlyCollection<string> Errors)> SaveGroupAsync(InventoryGroup x, CancellationToken t) { var e = x.Validate(); if (e.Count > 0) return (false, e); return await repository.SaveGroupAsync(x, t) ? (true, []) : (false, ["El grupo ya existe o el inventario está cerrado."]); } public ValueTask<bool> DeleteGroupAsync(int id, string code, string supplier, CancellationToken t) => repository.DeleteGroupAsync(id, code.Trim(), supplier.Trim(), t); public ValueTask<bool> CloseAsync(int id, decimal entries, decimal exits, CancellationToken t) => repository.CloseAsync(id, entries, exits, t); }
